import type { ExpansionSpec } from './types';
const references = {
 influenza: ['CDC: Influenza genetic change and reassortment', 'https://www.cdc.gov/flu/php/viruses/change.html'],
 foscarnet: ['DailyMed: Foscavir prescribing information', 'https://dailymed.nlm.nih.gov/dailymed/getFile.cfm?setid=a09299d5-9c55-4cef-aed0-3a6a45532289&type=pdf'],
 amoeba: ['CDC DPDx: Free-living amebic infections', 'https://www.cdc.gov/dpdx/freelivingamebic/index.html'],
 giardia: ['CDC DPDx: Giardiasis', 'https://www.cdc.gov/dpdx/giardiasis/index.html'],
 crypto: ['CDC DPDx: Cryptosporidiosis', 'https://www.cdc.gov/dpdx/cryptosporidiosis/index.html'],
 trichinella: ['CDC DPDx: Trichinellosis', 'https://www.cdc.gov/dpdx/trichinellosis/index.html'],
 echinococcus: ['CDC DPDx: Echinococcosis', 'https://www.cdc.gov/dpdx/echinococcosis/index.html'],
 leishmania: ['CDC DPDx: Leishmaniasis', 'https://www.cdc.gov/dpdx/leishmaniasis/index.html'],
 babesia: ['CDC DPDx: Babesiosis', 'https://www.cdc.gov/dpdx/babesiosis/index.html'],
 toxoplasma: ['CDC DPDx: Toxoplasmosis', 'https://www.cdc.gov/dpdx/toxoplasmosis/index.html'],
 cruzi: ['CDC DPDx: American trypanosomiasis', 'https://www.cdc.gov/dpdx/trypanosomiasisAmerican/index.html'],
 enterobius: ['CDC DPDx: Enterobiasis', 'https://www.cdc.gov/dpdx/enterobiasis/index.html'],
 hookworm: ['CDC DPDx: Hookworm', 'https://www.cdc.gov/dpdx/hookworm/index.html'],
 ascaris: ['CDC DPDx: Ascariasis', 'https://www.cdc.gov/dpdx/ascariasis/index.html'],
 trichuris: ['CDC DPDx: Trichuriasis', 'https://www.cdc.gov/dpdx/trichuriasis/index.html'],
 onchocerca: ['CDC DPDx: Onchocerciasis', 'https://www.cdc.gov/dpdx/onchocerciasis/index.html'],
 filaria: ['CDC DPDx: Lymphatic filariasis', 'https://www.cdc.gov/dpdx/lymphaticfilariasis/index.html'],
 acyclovir: ['NCI Drug Dictionary: Acyclovir mechanism', 'https://www.cancer.gov/publications/dictionaries/cancer-drug/def/acyclovir'],
 fluconazole: ['NCI Drug Dictionary: Fluconazole mechanism', 'https://www.cancer.gov/publications/dictionaries/cancer-drug/def/fluconazole'],
 hiv: ['NIH ClinicalInfo HIV glossary, mechanism further reading', 'https://clinicalinfo.hiv.gov/en/glossary'],
 parasite: ['CDC parasite biology overview, further reading', 'https://www.cdc.gov/parasites/about/index.html'],
 malaria: ['CDC DPDx: Malaria life cycle and morphology', 'https://www.cdc.gov/dpdx/malaria/index.html'],
 strongyloides: ['CDC DPDx: Strongyloidiasis life cycle', 'https://www.cdc.gov/dpdx/strongyloidiasis/index.html'],
 schistosoma: ['CDC DPDx: Schistosomiasis biology', 'https://www.cdc.gov/dpdx/schistosomiasis/index.html'],
 cysticercosis: ['CDC DPDx: Cysticercosis transmission', 'https://www.cdc.gov/dpdx/cysticercosis/index.html'],
 pharm: ['Open RN Nursing Pharmacology, 2nd edition, further reading', 'https://www.ncbi.nlm.nih.gov/books/NBK595000/'],
 micro: ['Medical Microbiology, 4th edition, molecular mechanisms further reading', 'https://www.ncbi.nlm.nih.gov/books/NBK7627/'],
 linezolid: ['DailyMed: Linezolid prescribing information', 'https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=ab1b4ab5-7338-4b01-963b-43eeb4c9cf1c'],
 daptomycin: ['DailyMed: Daptomycin prescribing information', 'https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c305bc9f-8aeb-40de-8492-154929764daf'],
 rifampin: ['NCI Drug Dictionary: Rifampin mechanism', 'https://www.cancer.gov/publications/dictionaries/cancer-drug/def/rifampin'],
 doxycycline: ['NCI Drug Dictionary: Doxycycline mechanism', 'https://www.cancer.gov/publications/dictionaries/cancer-drug/def/doxycycline-hyclate'],
 fosfomycin: ['DailyMed: Fosfomycin prescribing information', 'https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=48e352bc-52ea-4778-905a-60ef38a5c18a'],
 tb: ['CDC: Adverse events during tuberculosis treatment', 'https://www.cdc.gov/tb/hcp/treatment/adverse-events.html'],
 isoniazid: ['DailyMed: Isoniazid prescribing information', 'https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=6dab7b7b-a3a9-47ef-b423-134bc6970d8b&type=display'],
} satisfies Record<string,[string,string]>;
let serial = 200;
function q(subject: 'Microbiology'|'Pharmacology', system: string, topic: string, stem: string, answer: string, explanation: string, wrong: [string,string][], objective: string, ref: keyof typeof references = subject === 'Microbiology' ? 'micro' : 'pharm', reasoning: 'recognition'|'application'|'integration' = 'application'): ExpansionSpec {
 return {code:`op26x-${String(++serial).padStart(4,'0')}`,concept:topic.toLowerCase().replace(/[^a-z0-9]+/g,'-'),reasoning,difficultyReason:`${reasoning==='integration'?'Combine the experimental or clinical findings and infer the intermediate mechanism':reasoning==='recognition'?'Identify the explicitly cued molecular target':'Apply a molecular mechanism to the stated perturbation'}: ${objective}`,evidenceNote:`${references[ref][0]}: official bibliographic or indexed text checked 2026-10-29. Supports stable molecular framework; no current treatment regimen is asserted. Book-level further reading does not independently validate every distractor and no expert review is claimed.`,semanticReviewNote:`Compared with batches 04/05 microbial identification and classic toxin objectives, and 09/10 physiology, adaptive immunity, genetics and microbial virulence topics. Distinct objective: ${objective}`,concerns:[],question:{subject,system,topic,stem,options:[[answer,explanation],...wrong],explanation,objective,reference:references[ref],exam:'Step 1',difficulty:{recognition:1,application:2,integration:3}[reasoning]}};
}
export const specs: ExpansionSpec[] = [
q('Pharmacology','General Principles','Vancomycin precursor binding','A glycopeptide antibiotic blocks cell-wall assembly without binding the penicillin-binding enzyme itself. It instead binds terminal peptide residues on the precursor. Which target explains vancomycin activity?', 'D-alanyl-D-alanine terminus', 'Vancomycin binds the terminal D-alanyl-D-alanine of susceptible peptidoglycan precursors and interferes with wall assembly. Substrate binding distinguishes its action from beta-lactam binding to transpeptidase enzymes, even though both impair the cell wall.', [['Bacterial DNA gyrase','Gyrase inhibition is a fluoroquinolone mechanism rather than glycopeptide precursor binding.'],['The 30S aminoacyl-tRNA entry site','That ribosomal site does not account for peptidoglycan precursor sequestration.'],['Human cholesterol in the plasma membrane','Vancomycin does not act by binding human membrane cholesterol.']], 'Distinguish peptidoglycan precursor binding from direct penicillin-binding protein inhibition.'),
q('Pharmacology','General Principles','Vancomycin D lactate resistance','An enterococcal isolate becomes resistant to vancomycin after replacing the terminal D-alanine of its wall precursor with D-lactate. What is the most direct effect of this substitution?', 'Reduced antibiotic affinity for its precursor target', 'Changing D-alanyl-D-alanine to D-alanyl-D-lactate alters the glycopeptide binding site and markedly reduces affinity. The organism need not eliminate peptidoglycan altogether; target remodeling permits wall synthesis while evading strong vancomycin binding.', [['Direct hydrolysis of every vancomycin molecule','The described mechanism changes the target rather than enzymatically destroying the drug.'],['Increased binding to the unchanged precursor','The precursor is changed and drug affinity falls rather than rises.'],['Loss of all bacterial ribosomes','Ribosomal destruction does not explain a specific wall-precursor substitution.']], 'Infer target-affinity reduction from a defined peptidoglycan precursor substitution.'),
q('Pharmacology','General Principles','Daptomycin membrane depolarization','A lipopeptide rapidly kills susceptible gram-positive bacteria by calcium-dependent interaction with their membrane. Protein and nucleic acid synthesis stop secondarily. Which primary effect best describes daptomycin?', 'Disruption of membrane potential', 'Daptomycin associates with susceptible bacterial membranes and causes rapid depolarization, disrupting essential cellular processes. The resulting inhibition of macromolecule synthesis is downstream, rather than evidence that its primary target is a ribosomal subunit.', [['Direct 50S initiation-complex blockade','That is a ribosomal mechanism rather than the lipopeptide membrane effect.'],['Competitive inhibition of bacterial folate synthesis','Daptomycin does not primarily act through the folate pathway.'],['Specific inhibition of mycobacterial mycolic acid production','That is not the mechanism of this membrane-active lipopeptide.']], 'Distinguish primary membrane depolarization from downstream biosynthetic failure.','daptomycin'),
q('Pharmacology','Respiratory','Daptomycin pulmonary surfactant limitation','A bacterial isolate is susceptible to daptomycin in standard broth, but the drug is not used for routine bronchial-alveolar pneumonia. Which local factor explains this discrepancy?', 'Inactivation by pulmonary surfactant', 'Activity in standard culture does not account for every tissue environment. Pulmonary surfactant inhibits daptomycin activity, explaining why an in-vitro susceptible organism does not make the drug suitable for routine alveolar pneumonia.', [['Complete absence of bacteria from all lung infections','Pneumonia can be bacterial, so this does not explain the drug-specific limitation.'],['Conversion of every gram-positive lung organism into a fungus','The limitation concerns local drug activity rather than organism transformation.'],['Universal inability of all intravenous drugs to enter lungs','Many intravenous antimicrobials treat lung infection; this is not a universal route problem.']], 'Connect a tissue-specific inhibitor with failure to extrapolate broth susceptibility.','daptomycin','integration'),
q('Pharmacology','General Principles','Linezolid initiation complex','An oxazolidinone binds bacterial 23S RNA on the 50S subunit. The ribosomal subunits cannot assemble a functional translation initiation complex. Which step is directly blocked?', 'Formation of the functional 70S initiation complex', 'Linezolid binding to the 50S-associated 23S RNA prevents assembly of a functional initiation complex. This targets the start of bacterial translation rather than DNA replication or a membrane permeability step, differentiating it from several other antimicrobial classes.', [['DNA-dependent RNA polymerase transcription','That is a rifamycin target rather than linezolid initiation blockade.'],['Peptidoglycan D-alanine production','The described target is ribosomal RNA rather than a wall precursor enzyme.'],['Fungal ergosterol synthesis','A bacterial ribosome mechanism does not target fungal sterol synthesis.']], 'Locate linezolid action at translation initiation rather than transcription.','linezolid'),
q('Pharmacology','Nervous System','Linezolid serotonergic interaction','A patient taking a serotonin reuptake inhibitor develops agitation, diaphoresis, hyperreflexia and clonus after linezolid is added. Which additional property of linezolid explains the interaction?', 'Reversible monoamine oxidase inhibition', 'Linezolid has monoamine oxidase-inhibiting activity that can increase serotonergic effects when combined with serotonergic drugs. Clonus and hyperreflexia support serotonin toxicity rather than attributing all neurologic symptoms to its antibacterial ribosomal target.', [['Strong blockade of dopamine receptors','That mechanism would not best explain the characteristic serotonergic interaction and clonus.'],['Direct inhibition of acetylcholinesterase','The described drug interaction is mediated by monoamine handling rather than cholinesterase blockade.'],['Complete antagonism of every serotonin receptor','Receptor antagonism would not explain amplified serotonergic toxicity.']], 'Integrate a drug interaction and neuromuscular pattern to identify a nonantibacterial target.','linezolid','integration'),
q('Pharmacology','General Principles','Rifampin bacterial transcription target','In an experiment, rifampin stops production of new bacterial RNA while previously synthesized RNA can still be translated briefly. Which enzyme is directly inhibited?', 'DNA-dependent RNA polymerase', 'Rifampin inhibits susceptible bacterial DNA-dependent RNA polymerase, reducing transcription. Preexisting transcripts may remain available transiently, so brief residual translation is compatible with a primary transcription block rather than evidence of direct ribosomal inhibition.', [['DNA ligase as the transcription enzyme','DNA ligase joins nucleic acid breaks rather than synthesizing RNA transcripts.'],['Human reverse transcriptase','Rifampin antibacterial activity does not depend on a human reverse transcriptase.'],['Bacterial aminoacyl-tRNA synthetase in every organism','That is not rifampin principal transcriptional target.']], 'Use continued translation of old RNA to localize an antimicrobial transcription block.','rifampin'),
q('Pharmacology','General Principles','Isoniazid prodrug activation','A mycobacterial mutant has markedly reduced catalase-peroxidase activity encoded by katG and becomes resistant to isoniazid. What drug-related step is impaired?', 'Conversion of isoniazid into its active intracellular form', 'Isoniazid requires mycobacterial activation, classically involving KatG, before its active products inhibit mycolic acid synthesis. Loss of activation can therefore produce resistance without requiring the downstream synthetic target to be absent.', [['Extracellular binding of all antibiotics to albumin','KatG is an intracellular microbial activation factor rather than a host binding protein.'],['Direct synthesis of human cholesterol','Mycobacterial catalase-peroxidase does not synthesize human sterols.'],['Normal activation becoming stronger in the mutant','Reduced activation explains resistance rather than increased drug action.']], 'Explain resistance caused by failure to activate an antimicrobial prodrug.','isoniazid'),
q('Pharmacology','Nervous System','Isoniazid pyridoxine neuropathy','A malnourished patient treated with isoniazid develops distal tingling and reduced vibration sensation. Which vitamin-related disturbance most directly contributes to this recognized toxicity?', 'Reduced availability of active vitamin B6', 'Isoniazid can interfere with pyridoxine metabolism and contribute to peripheral neuropathy, especially in susceptible patients. The mechanism explains the role of vitamin B6 in prevention or correction; it does not imply that any amount of vitamin supplementation is harmless.', [['A primary excess of vitamin C','That does not explain the characteristic isoniazid-associated neuropathy mechanism.'],['Complete absence of vitamin K-dependent clotting','That would primarily cause bleeding rather than this distal sensory pattern.'],['Increased active pyridoxine as the established toxic mechanism','The classic association concerns impaired vitamin B6 availability and function.']], 'Connect isoniazid sensory toxicity to a specific vitamin cofactor disturbance.','tb'),
q('Pharmacology','General Principles','Ethambutol arabinogalactan synthesis','A mycobacterial culture exposed to ethambutol shows reduced polymerization of arabinan components of the cell envelope. Which enzyme class is the principal target?', 'Arabin osyltransferases involved in cell-wall synthesis', 'Ethambutol inhibits arabinosyltransferase-dependent synthesis of arabinan-containing mycobacterial wall components. This differs from inhibiting mycolic acid synthesis or bacterial transcription; the shared cell-envelope outcome does not imply an identical molecular target.', [['DNA-dependent RNA polymerase','That is a rifampin-associated target rather than arabinan polymerization.'],['Bacterial 30S ribosomal decoding center','A translation target does not explain the specific arabinan synthetic effect.'],['Human aromatase','A human steroid enzyme is not the mycobacterial wall-polymerization target.']], 'Distinguish arabinan assembly inhibition from other mycobacterial envelope targets.'),
q('Pharmacology','Nervous System','Ethambutol optic toxicity','A patient receiving several antituberculous drugs develops reduced visual acuity and difficulty distinguishing red from green. Which agent is most characteristically associated with this toxicity?', 'Ethambutol', 'Ethambutol can cause optic neuropathy with reduced acuity and color discrimination. The pattern differs from the distal sensory neuropathy associated with isoniazid; symptoms require assessment rather than assuming blurred vision is an expected harmless treatment effect.', [['Isoniazid as the characteristic red-green optic toxicant','Isoniazid more classically causes peripheral neuropathy than this optic pattern.'],['Pyrazinamide as the characteristic optic toxicant','Its better-known adverse effects include hyperuricemia and hepatotoxicity.'],['Pyridoxine as a guaranteed explanation for every visual change','The classic antituberculous association in this pattern is ethambutol.']], 'Distinguish antituberculous optic neuropathy from peripheral neurotoxicity.','tb'),
q('Pharmacology','Renal','Pyrazinamide hyperuricemia','A patient taking a multidrug tuberculosis regimen develops an elevated serum urate and an acute gout flare. Which drug is most characteristically associated with impaired urate handling in this context?', 'Pyrazinamide', 'Pyrazinamide commonly raises uric acid through altered renal urate handling and can precipitate gout in susceptible patients. An elevated urate alone is not the same as symptomatic gout, but the joint presentation and drug exposure support this adverse-effect link.', [['Ethambutol as the only possible cause of every gout flare','Although drugs can have overlapping effects, pyrazinamide is a classic strong association here.'],['Pyridoxine as a urate-retaining antituberculous antibiotic','Pyridoxine is a vitamin supplement rather than the implicated antibiotic.'],['Rifampin solely because it colors body fluids','Fluid discoloration does not establish the urate-handling mechanism.']], 'Associate a tuberculosis drug with a symptomatic urate-handling adverse effect.','tb'),
q('Pharmacology','General Principles','Bedaquiline ATP synthase target','A diarylquinoline reduces ATP production in susceptible mycobacteria by inhibiting the membrane rotary enzyme responsible for ATP synthesis. Which target explains bedaquiline action?', 'Mycobacterial ATP synthase', 'Bedaquiline impairs mycobacterial energy generation by inhibiting ATP synthase. This target differs from nucleic acid polymerases and wall-assembly enzymes, so growth arrest does not imply that it acts through a conventional ribosomal pathway.', [['Bacterial DNA-dependent RNA polymerase','That is a rifamycin target rather than the membrane energy-generating enzyme.'],['Peptidoglycan transpeptidase','Transpeptidase inhibition disrupts cross-linking rather than directly blocking ATP synthase.'],['Human hemoglobin synthesis','That does not describe the mycobacterial membrane target.']], 'Identify the energy-generating target of a diarylquinoline antimycobacterial drug.'),
q('Pharmacology','General Principles','Cycloserine D alanine synthesis','An antibiotic inhibits alanine racemase and D-alanyl-D-alanine ligase. Which component of bacterial wall assembly is most directly depleted?', 'D-alanine-containing peptide precursor', 'Cycloserine blocks production and joining of D-alanine needed for the peptidoglycan peptide stem. Unlike vancomycin, which binds the completed terminal motif, it interferes with enzymatic precursor formation upstream of incorporation into the wall.', [['Ergosterol in a fungal membrane','The enzymes described are involved in bacterial peptide precursor synthesis.'],['Bacterial messenger RNA capping','These enzymes do not add caps to bacterial transcripts.'],['Human basement-membrane collagen','Bacterial D-alanine wall synthesis is distinct from human collagen formation.']], 'Locate alanine racemase and D-alanine ligase inhibition upstream of wall precursor incorporation.'),
q('Pharmacology','General Principles','Tetracycline aminoacyl tRNA blockade','An antibacterial drug binds the 30S subunit and prevents incoming charged transfer RNA from occupying the ribosomal acceptor site. Which translation step is directly limited?', 'Addition of the next aminoacyl-tRNA to the growing chain machinery', 'Tetracyclines interfere with aminoacyl-tRNA access at the bacterial ribosome, preventing continued elongation. The mechanism is distinct from inhibition of RNA polymerase or cell-wall cross-linking, even though all can ultimately stop bacterial growth.', [['Initiation of bacterial RNA transcription','The described block is translation rather than synthesis of an RNA transcript.'],['Cross-linking of peptidoglycan peptide stems','That is a wall enzyme step rather than a ribosomal acceptor-site event.'],['Fungal beta-glucan synthesis','A bacterial 30S target does not directly synthesize fungal wall glucan.']], 'Map tetracycline target binding to incoming charged-tRNA access.','doxycycline'),
q('Pharmacology','General Principles','Macrolide translocation arrest','A macrolide binds the bacterial 50S ribosomal subunit. Peptide elongation stalls because movement of the ribosome along the messenger RNA is impaired. Which process is being inhibited?', 'Ribosomal translocation', 'Macrolide binding to the large ribosomal subunit interferes with elongation and translocation. This differs from preventing charged tRNA entry at the 30S acceptor site or inhibiting DNA replication; knowing the affected step separates classes that all reduce protein synthesis.', [['Formation of an RNA transcript by RNA polymerase','The mechanism acts after transcription at the translating ribosome.'],['Synthesis of D-alanine from L-alanine','That enzymatic step belongs to peptidoglycan precursor synthesis.'],['Formation of a fungal mitotic spindle','A bacterial ribosome is not a fungal spindle apparatus.']], 'Distinguish macrolide translocation inhibition from other translation blocks.'),
q('Pharmacology','Gastrointestinal','Clindamycin colonization resistance','After clindamycin exposure, a patient develops toxin-positive Clostridioides difficile colitis. Which ecological effect of antimicrobial treatment most directly enables the infection?', 'Disruption of protective intestinal microbial communities', 'Antibiotics can reduce colonization resistance by changing the intestinal microbial community, permitting C difficile expansion and toxin-mediated disease. This is an indirect ecological consequence rather than evidence that clindamycin itself is a bacterial toxin.', [['Conversion of the antibiotic into C difficile toxin','The organism produces toxins; the drug alters the ecological setting.'],['Guaranteed elimination of every intestinal organism','Dysbiosis does not require total sterilization of the intestine.'],['Direct increase in human lactase activity','Lactase induction does not explain toxin-positive antibiotic-associated colitis.']], 'Explain antibiotic-associated colitis through loss of colonization resistance.'),
q('Pharmacology','Hematology','Chloramphenicol dose related marrow suppression','A patient receiving prolonged chloramphenicol develops a reversible reduction in blood-cell production associated with mitochondrial protein synthesis inhibition. Which host cellular similarity contributes to this toxicity?', 'Mitochondrial ribosomes retain bacterial-like features', 'Mitochondrial translation machinery shares features with bacterial ribosomes, allowing some antibacterial protein-synthesis inhibitors to affect host cells. Reversible dose-related suppression is distinct from the rare idiosyncratic aplastic anemia also associated with chloramphenicol.', [['Human red-cell precursors possess peptidoglycan walls','Human cells do not have bacterial peptidoglycan walls.'],['Mitochondria synthesize proteins using nuclear spliceosomes','Splicing machinery is not the translation target that explains this toxicity.'],['All marrow toxicity is necessarily the same idiosyncratic syndrome','Dose-related suppression and rare aplastic anemia have distinct descriptions.']], 'Use mitochondrial ribosomal similarity to explain a host effect of antibacterial translation inhibition.'),
q('Pharmacology','General Principles','Aminoglycoside anaerobe uptake limitation','An aminoglycoside is active against an aerobic bacterial isolate but lacks useful activity against an obligate anaerobe with a similar ribosomal target. Which uptake requirement best explains the difference?', 'Energy-dependent transport linked to aerobic conditions', 'Aminoglycoside entry into bacteria depends on energy-requiring membrane transport that is ineffective under anaerobic conditions. A susceptible ribosomal target alone is insufficient if the drug cannot reach it, distinguishing uptake limitation from acquired target mutation.', [['Anaerobes universally lack ribosomes','All bacteria require ribosomes for protein synthesis.'],['The drug must first bind fungal ergosterol','Aminoglycosides do not depend on a fungal membrane sterol for bacterial entry.'],['Human renal excretion creates the anaerobic resistance in culture','The difference is observed in microbial uptake rather than host clearance.']], 'Separate antibiotic uptake requirements from presence of a susceptible intracellular target.'),
q('Pharmacology','General Principles','Sulfonamide PABA competition','A bacterial culture stops making folate when exposed to a structural analog of para-aminobenzoic acid. Excess PABA reduces inhibition. Which enzyme is the likely target?', 'Dihydropteroate synthase', 'Sulfonamides compete with PABA in bacterial folate synthesis at dihydropteroate synthase. Humans obtain folate from the diet rather than using this synthetic pathway, contributing to selectivity; the target is upstream of dihydrofolate reductase.', [['Dihydrofolate reductase','That is a downstream folate enzyme targeted by trimethoprim rather than the PABA step.'],['DNA-dependent RNA polymerase','Transcription inhibition does not specifically explain competition with PABA.'],['Bacterial peptidyl transferase','A ribosomal catalyst does not synthesize folate from PABA.']], 'Use substrate competition to identify the upstream bacterial folate enzyme.'),
q('Pharmacology','General Principles','Trimethoprim reduced folate regeneration','After a bacterial folate precursor is formed normally, trimethoprim prevents regeneration of tetrahydrofolate needed for one-carbon transfers. Which enzyme is inhibited?', 'Bacterial dihydrofolate reductase', 'Trimethoprim preferentially inhibits bacterial dihydrofolate reductase, reducing tetrahydrofolate availability for nucleotide synthesis. It acts downstream of sulfonamides, explaining why sequential pathway inhibition can have a stronger combined effect than either isolated block.', [['Dihydropteroate synthase','That enzyme acts earlier at the PABA-containing precursor step.'],['Alanine racemase','D-alanine formation belongs to peptidoglycan rather than folate metabolism.'],['Fungal squalene epoxidase','A sterol enzyme does not regenerate reduced folate.']], 'Locate trimethoprim downstream of the PABA-dependent folate step.'),
q('Pharmacology','General Principles','Fluoroquinolone topoisomerase inhibition','A bacterial cell exposed to a fluoroquinolone accumulates DNA damage when replication-associated topoisomerase complexes cannot complete normal strand resealing. Which enzyme group is targeted?', 'DNA gyrase and topoisomerase IV', 'Fluoroquinolones inhibit bacterial type II topoisomerases involved in DNA topology and segregation. Stabilizing damaging enzyme-DNA intermediates interrupts replication; this is distinct from rifampin inhibition of RNA polymerase despite both impairing nucleic acid processes.', [['DNA-dependent RNA polymerase','That transcriptional enzyme is not the defining fluoroquinolone target.'],['Dihydropteroate synthase','A folate synthesis enzyme does not directly manage DNA supercoiling and segregation.'],['Peptidoglycan transpeptidases','Wall cross-linking enzymes do not reseal DNA strand breaks.']], 'Distinguish direct bacterial topoisomerase inhibition from transcription blockade.'),
q('Pharmacology','General Principles','Metronidazole reductive activation','Metronidazole causes DNA injury in susceptible anaerobes after its nitro group is reduced by microbial electron-transfer pathways. Which property explains selective activation?', 'Formation of reactive intermediates under a low-redox intracellular environment', 'Reduction of the nitro group generates reactive metabolites that damage microbial DNA in susceptible organisms. The activation context helps explain anaerobic activity; metronidazole is not simply a universally active direct human DNA polymerase inhibitor.', [['An obligatory oxygen-rich activation step in every bacterium','The classic activation is associated with susceptible low-redox anaerobic pathways.'],['Binding to the human estrogen receptor','That does not explain the microbial nitro-reduction mechanism.'],['Inhibition of fungal beta-glucan synthesis','The described drug causes reductively activated DNA injury rather than a fungal wall block.']], 'Connect anaerobic reductive metabolism with activation of a DNA-damaging antimicrobial.'),
q('Pharmacology','General Principles','Fosfomycin MurA early precursor block','Fosfomycin inhibits transfer of an enolpyruvyl group to UDP-N-acetylglucosamine. Which pathway stage is directly interrupted?', 'An early cytoplasmic step in peptidoglycan precursor synthesis', 'MurA catalyzes an early step that commits a sugar precursor toward bacterial peptidoglycan production. Fosfomycin inhibition acts before late extracellular cross-linking, so sharing a cell-wall outcome with beta-lactams does not mean sharing their enzyme target.', [['Late transpeptidase cross-linking as the directly described reaction','The enolpyruvyl transfer occurs earlier in cytoplasmic precursor synthesis.'],['Fungal ergosterol demethylation','The sugar precursor reaction is not a fungal sterol pathway.'],['Initiation of bacterial translation','MurA is a wall precursor enzyme rather than a ribosomal initiation component.']], 'Distinguish early cytoplasmic wall precursor inhibition from late cross-linking.','fosfomycin'),
q('Pharmacology','General Principles','Polymyxin outer membrane disruption','A cationic peptide binds negatively charged lipid A and phospholipids in a gram-negative envelope, increasing membrane permeability. Which antibacterial mechanism is demonstrated?', 'Polymyxin-mediated membrane disruption', 'Polymyxins interact with gram-negative outer membrane lipids and disrupt membrane integrity. Their effect is distinct from inhibiting an intracellular ribosome or a peptidoglycan enzyme, and the membrane interaction also contributes to limitations in host selectivity.', [['Direct bacterial 50S peptidyl transferase inhibition','The described lipid interaction is a membrane mechanism rather than a ribosomal one.'],['Inhibition of viral neuraminidase','A viral release enzyme is not a gram-negative lipid target.'],['Blockade of fungal microtubules','The gram-negative envelope lacks the fungal mitotic apparatus targeted by that mechanism.']], 'Identify a membrane-active antibacterial from its lipid A interaction.'),
q('Pharmacology','General Principles','Azole sterol demethylation','A fungal culture exposed to fluconazole accumulates methylated sterol intermediates while its normal membrane sterol decreases. Which reaction is most directly inhibited?', 'Lanosterol 14-alpha-demethylation', 'Azoles inhibit a fungal cytochrome P450-dependent sterol demethylase, reducing normal ergosterol synthesis. Accumulating abnormal sterols also alter membrane function. This is a synthesis defect rather than direct binding of a pore-forming drug to existing sterol.', [['Beta-glucan polymerization','Glucan synthesis is a cell-wall target of echinocandins rather than azoles.'],['Squalene epoxidation','That earlier sterol reaction is the principal target of terbinafine.'],['Microtubule assembly','Mitotic microtubules are not the sterol-demethylating enzyme.']], 'Identify the inhibited sterol reaction from azole-associated precursor accumulation.','fluconazole'),
q('Pharmacology','General Principles','Amphotericin sterol pores','A polyene antifungal binds ergosterol already present in a fungal membrane and produces ion leakage. Which immediate effect explains fungal cell injury?', 'Increased membrane permeability through drug-sterol assemblies', 'Amphotericin B interacts with membrane ergosterol and disrupts membrane integrity, including formation of permeabilizing assemblies. It does not primarily inhibit the enzyme that makes ergosterol; leakage of intracellular ions is downstream of membrane injury.', [['Blockade of bacterial DNA gyrase','Gyrase is a bacterial DNA target rather than a fungal membrane sterol.'],['Inhibition of folate synthesis from PABA','That antibacterial pathway does not explain sterol-dependent ion leakage.'],['Prevention of viral capsid uncoating','Viral uncoating is unrelated to the observed fungal membrane damage.']], 'Distinguish binding to existing fungal sterol from inhibition of sterol synthesis.'),
q('Pharmacology','General Principles','Echinocandin glucan synthase','A Candida isolate exposed to an echinocandin develops a weakened cell wall despite maintaining its membrane ergosterol synthesis. Which enzyme is the direct drug target?', 'Beta-1,3-D-glucan synthase', 'Echinocandins inhibit synthesis of a major fungal wall glucan, weakening the wall and its osmotic protection. The target is separate from sterol synthesis, so preserved ergosterol production is compatible with marked antifungal activity.', [['Lanosterol demethylase','This enzyme supports sterol synthesis rather than wall glucan assembly.'],['Bacterial transpeptidase','Fungal walls do not use the bacterial peptidoglycan cross-linking target.'],['Viral reverse transcriptase','A viral replication enzyme does not make the fungal cell wall.']], 'Localize echinocandin action to fungal wall polysaccharide synthesis.'),
q('Pharmacology','General Principles','Terbinafine squalene accumulation','A dermatophyte culture accumulates squalene and produces less ergosterol after exposure to terbinafine. Which enzyme blockade best explains both biochemical changes?', 'Squalene epoxidase inhibition', 'Terbinafine inhibits squalene epoxidase early in fungal sterol synthesis. The upstream substrate accumulates while downstream ergosterol production falls. These linked changes distinguish its target from the later demethylase inhibited by azoles.', [['Glucan synthase inhibition','A wall glucan block does not directly predict squalene accumulation.'],['DNA gyrase inhibition','This bacterial DNA mechanism does not explain fungal sterol precursors.'],['D-alanine ligase inhibition','Fungal sterol synthesis does not require the bacterial wall peptide enzyme.']], 'Infer the blocked sterol step from simultaneous substrate accumulation and product depletion.'),
q('Pharmacology','General Principles','Flucytosine fungal activation','A fungal strain loses cytosine deaminase activity and becomes resistant to flucytosine despite normal uptake. Which conversion is most directly impaired?', 'Conversion of flucytosine to fluorouracil inside the fungus', 'Fungal cytosine deaminase converts flucytosine to fluorouracil, which is further metabolized into compounds that impair RNA and DNA synthesis. Loss of this activation step can cause resistance even when the drug enters the cell normally.', [['Conversion of ergosterol to cholesterol','This sterol conversion is unrelated to cytosine deaminase activation.'],['Formation of bacterial D-alanine','A fungal pyrimidine prodrug does not require peptidoglycan precursor formation.'],['Cleavage of HIV polyproteins','The enzyme described is fungal cytosine deaminase rather than viral protease.']], 'Explain antifungal prodrug resistance through loss of intracellular metabolic activation.'),
q('Pharmacology','General Principles','Griseofulvin mitotic spindle','A dermatophyte exposed to griseofulvin shows abnormal mitotic spindles and impaired nuclear division. Which cellular structure is directly involved in the drug mechanism?', 'Fungal microtubules', 'Griseofulvin interferes with fungal microtubule function and mitosis. Its activity against dermatophytes is associated with incorporation into newly formed keratin, but the immediate experimental spindle defect is a cytoskeletal effect rather than a wall synthetic block.', [['Peptidoglycan peptide bridges','Dermatophytes lack the bacterial peptidoglycan target.'],['The viral neuraminidase active site','A viral release enzyme cannot explain fungal spindle disruption.'],['Fungal beta-glucan as a microtubule','Glucan is a wall carbohydrate rather than the mitotic spindle structure.']], 'Connect an antifungal-induced spindle abnormality with microtubule disruption.'),
q('Pharmacology','General Principles','Acyclovir viral kinase selectivity','Acyclovir is activated much more efficiently in herpes-infected cells than in nearby uninfected cells. Which viral enzyme catalyzes its initial phosphorylation in susceptible herpes simplex virus?', 'Viral thymidine kinase', 'Herpes simplex viral thymidine kinase performs the initial activation step for acyclovir. Cellular enzymes complete phosphorylation, and the triphosphate inhibits viral DNA synthesis. Preferential activation contributes to selectivity without implying that uninfected cells lack all kinases.', [['Viral neuraminidase','Neuraminidase promotes influenza release rather than acyclovir phosphorylation.'],['HIV integrase','Integrase inserts retroviral DNA into host DNA rather than phosphorylating acyclovir.'],['Bacterial beta-lactamase','A bacterial drug-hydrolyzing enzyme is not the herpes activation enzyme.']], 'Identify the viral enzyme responsible for selective initial acyclovir activation.','acyclovir'),
q('Pharmacology','General Principles','Foscarnet kinase bypass','A thymidine-kinase-deficient herpes isolate resists acyclovir but remains susceptible to foscarnet. Which pharmacologic property best accounts for retained susceptibility?', 'Direct polymerase inhibition without phosphorylation for activation', 'Foscarnet is a pyrophosphate analog that directly inhibits susceptible viral polymerases without requiring viral kinase activation. Loss of thymidine kinase can therefore spare its action, although polymerase changes can cause a separate resistance mechanism.', [['Dependence on the same missing thymidine kinase','Requiring the absent activating enzyme would not explain retained activity.'],['Selective inhibition of bacterial wall synthesis','Herpesviruses do not synthesize a peptidoglycan wall.'],['Binding only to an influenza release enzyme','An influenza-specific release mechanism does not explain herpes polymerase inhibition.']], 'Integrate a viral activation defect with a drug that bypasses that activation requirement.','foscarnet','integration'),
q('Pharmacology','General Principles','Oseltamivir virion release','Influenza-infected cells assemble virions normally during exposure to oseltamivir, but newly formed particles remain attached to sialic-acid-containing surfaces. Which viral enzyme is inhibited?', 'Neuraminidase', 'Influenza neuraminidase cleaves sialic acid and facilitates release of progeny virions. Its inhibition can impair particle release without directly stopping viral genome synthesis or the preceding assembly of structural components.', [['Reverse transcriptase','Influenza does not require a retroviral DNA intermediate.'],['HIV protease','This enzyme processes retroviral polyproteins rather than cleaving sialic acid.'],['Herpes thymidine kinase','The kinase activates certain herpes drugs and does not mediate influenza release.']], 'Localize an influenza release defect to sialic-acid cleavage.'),
q('Pharmacology','General Principles','Baloxavir cap dependent endonuclease','An influenza antiviral prevents cleavage of short capped fragments from host RNA that the virus normally uses to initiate its own messenger RNA. Which activity is inhibited?', 'Viral cap-dependent endonuclease', 'Baloxavir inhibits the influenza polymerase-associated endonuclease involved in cap snatching. Without the capped primers, viral messenger RNA synthesis is impaired. This early transcriptional mechanism differs from the neuraminidase-dependent release of completed virions.', [['Sialic-acid cleavage during release','That is the neuraminidase step rather than cap-primer acquisition.'],['Integration of viral DNA','Influenza replication does not require integrated viral DNA.'],['Peptidoglycan cross-link formation','Viruses do not assemble the bacterial wall targeted by this reaction.']], 'Distinguish influenza cap-primer acquisition from later virion release.'),
q('Pharmacology','General Principles','NRTI chain termination','An activated nucleoside analog is incorporated into HIV DNA by reverse transcriptase but lacks a usable three-prime hydroxyl group. What immediate consequence follows?', 'Failure to extend the nascent DNA chain', 'A usable three-prime hydroxyl is needed to form the next phosphodiester linkage. Incorporation of a chain-terminating nucleoside analog interrupts reverse transcription, unlike an allosteric inhibitor that can act without becoming part of the DNA.', [['More efficient cleavage of viral polyproteins','Polyprotein cleavage is a separate protease-mediated maturation step.'],['Prevention of attachment to CCR5 by DNA incorporation','CCR5 engagement occurs before the DNA synthesis step described.'],['Direct inhibition of fungal sterol synthesis','A retroviral DNA analog does not target fungal sterol enzymes.']], 'Predict the consequence of losing the chain-extending hydroxyl during reverse transcription.','hiv'),
q('Pharmacology','General Principles','NNRTI allosteric inhibition','A drug inhibits HIV reverse transcriptase by binding a non-substrate pocket, and the drug itself is never incorporated into viral DNA. Which class mechanism is demonstrated?', 'Non-nucleoside allosteric reverse transcriptase inhibition', 'Non-nucleoside reverse transcriptase inhibitors bind an allosteric site on susceptible HIV reverse transcriptase. They alter enzyme function without serving as DNA building blocks, separating this mechanism from nucleoside analog incorporation and chain termination.', [['Nucleoside analog incorporation into DNA','The stem explicitly states that the drug is not incorporated into DNA.'],['Integrase-mediated strand transfer blockade','Integrase acts on viral DNA insertion rather than RNA-to-DNA synthesis.'],['Protease-dependent particle maturation blockade','Protease inhibition acts on polyprotein cleavage rather than reverse transcriptase.']], 'Distinguish allosteric inhibition from incorporation-based reverse transcriptase inhibition.','hiv'),
q('Pharmacology','General Principles','HIV integrase strand transfer blockade','An HIV-infected cell makes double-stranded viral DNA, but a drug prevents covalent insertion of that DNA into host chromosomes. Which enzyme is directly inhibited?', 'HIV integrase', 'Integrase strand transfer inhibitors block insertion of viral DNA into host DNA. Successful reverse transcription can therefore precede the blocked step. The observation localizes the defect after DNA synthesis and before formation of a stable integrated provirus.', [['HIV reverse transcriptase','Viral DNA has already been synthesized, placing the block downstream of this enzyme.'],['HIV protease','Protease processes viral proteins during maturation rather than joining viral and host DNA.'],['Influenza neuraminidase','This enzyme cleaves sialic acid and does not integrate retroviral DNA.']], 'Locate antiretroviral action between viral DNA synthesis and chromosomal insertion.','hiv'),
q('Pharmacology','General Principles','HIV protease maturation block','HIV particles bud from a treated cell but contain uncleaved Gag-Pol precursors and have low infectivity. Which drug target most directly explains this finding?', 'Viral protease required for polyprotein processing', 'HIV protease cleaves viral polyproteins into functional structural proteins and enzymes during maturation. Inhibition can permit particle release while preventing formation of fully infectious mature particles, so the presence of extracellular virions does not prove normal maturation.', [['CCR5 entry coreceptor','Entry blockade does not specifically produce uncleaved proteins in budding progeny.'],['Reverse transcriptase RNA copying','Failure to copy RNA does not directly explain accumulated uncleaved polyproteins.'],['Host folate synthase','Humans do not synthesize folate through the bacterial PABA pathway.']], 'Infer a viral maturation target from released particles with uncleaved precursor proteins.','hiv'),
q('Pharmacology','General Principles','Maraviroc coreceptor specificity','An HIV entry inhibitor binds host CCR5. A viral variant that can enter using CXCR4 remains capable of infecting cells. What explains this escape?', 'Use of an alternative entry coreceptor not blocked by the drug', 'Maraviroc targets CCR5-mediated entry rather than every route of HIV attachment or fusion. A virus able to use CXCR4 can bypass this specific coreceptor block. The result concerns tropism, not necessarily a mutation of reverse transcriptase.', [['Guaranteed loss of every host CD4 molecule','Blocking CCR5 does not eliminate CD4 or all alternative coreceptors.'],['Restoration of a bacterial peptidoglycan wall','HIV does not possess a bacterial cell wall.'],['A requirement for influenza neuraminidase','HIV coreceptor choice is unrelated to influenza virion release.']], 'Explain receptor-specific entry inhibitor escape through alternative viral tropism.','hiv','integration'),
q('Pharmacology','General Principles','Enfuvirtide fusion conformational block','HIV binds CD4 and a coreceptor normally, but a peptide drug prevents gp41 from completing the structural rearrangement that brings membranes together. Which step is blocked?', 'Fusion of viral and host cell membranes', 'Enfuvirtide interferes with gp41-mediated membrane fusion after receptor engagement. It therefore acts before delivery of the viral core into the cell, rather than at the subsequent reverse transcription, integration, or polyprotein processing stages.', [['Insertion of completed viral DNA into chromosomes','Integration is downstream of entry and is mediated by integrase.'],['Cleavage of viral polyproteins','Protease-mediated maturation is a different stage of the life cycle.'],['Release of sialic acid from host surfaces','That is an influenza neuraminidase mechanism rather than HIV fusion.']], 'Map gp41 conformational inhibition to the membrane fusion step.','hiv'),
q('Pharmacology','General Principles','HCV NS5A replication complex','An experimental hepatitis C compound binds NS5A, a multifunctional nonenzymatic viral protein. Which process can be disrupted without directly targeting the RNA polymerase catalytic site?', 'Organization of viral replication and particle assembly', 'HCV NS5A participates in replication-complex organization and virion assembly. NS5A inhibitors affect these functions through a target distinct from the catalytic NS5B polymerase, illustrating that an effective antiviral target need not itself be an enzyme.', [['Peptidoglycan cross-linking in hepatitis C','Hepatitis C virus does not build a bacterial wall.'],['Integration of an obligatory hepatitis C DNA intermediate','HCV is an RNA virus without an obligatory integrated DNA stage.'],['Fungal ergosterol synthesis','A fungal membrane pathway is unrelated to the HCV replication complex.']], 'Distinguish a nonenzymatic HCV replication-complex target from the viral polymerase.'),
q('Pharmacology','General Principles','Sofosbuvir HCV polymerase target','A nucleotide analog metabolite inhibits the hepatitis C NS5B enzyme and interrupts production of new viral RNA. Which enzymatic activity is the direct target?', 'RNA-dependent RNA polymerase', 'HCV NS5B copies viral RNA using an RNA template. Activated sofosbuvir inhibits this RNA-dependent RNA polymerase through nucleotide analog action. The target differs from retroviral reverse transcriptase, which synthesizes DNA from an RNA template.', [['RNA-dependent DNA polymerase','That activity makes DNA and is characteristic of reverse transcriptase.'],['DNA-dependent RNA polymerase of bacteria','HCV NS5B uses an RNA template rather than bacterial chromosomal DNA.'],['Viral neuraminidase','Sialic-acid cleavage is not the RNA synthetic reaction described.']], 'Identify the template and product of the HCV polymerase inhibited by a nucleotide analog.'),
q('Pharmacology','General Principles','Albendazole parasite tubulin','A benzimidazole impairs helminth microtubules and reduces nutrient uptake. Which molecular interaction is most directly responsible for albendazole action?', 'Binding parasite beta-tubulin and inhibiting microtubule assembly', 'Albendazole binds parasite tubulin and impairs microtubule-dependent functions, including nutrient handling. Progressive metabolic depletion follows. This differs from directly depolarizing a worm neuromuscular membrane or blocking its folate pathway.', [['Activation of viral reverse transcriptase','Helminths do not depend on a viral reverse transcription step.'],['Inhibition of bacterial transpeptidases','A helminth does not build a bacterial peptidoglycan wall.'],['Antagonism of human histamine H2 receptors','Gastric acid receptor blockade does not explain parasite microtubule injury.']], 'Connect benzimidazole binding with helminth microtubule dysfunction.'),
q('Pharmacology','General Principles','Ivermectin invertebrate chloride channels','A nematode becomes paralyzed after a drug increases chloride conductance through invertebrate glutamate-gated channels. Which electrical change explains the paralysis?', 'Hyperpolarization of susceptible nerve and muscle cells', 'Ivermectin potentiates invertebrate glutamate-gated chloride channels, increasing chloride conductance and reducing excitability. The resulting paralysis reflects membrane electrophysiology rather than microtubule depletion. Mammalian channel distribution and limited brain entry contribute to selectivity.', [['Persistent depolarization from direct sodium influx','The stated chloride-channel effect favors reduced excitability rather than sodium-driven firing.'],['Direct cleavage of parasite DNA by a protease','A chloride channel does not enzymatically cleave DNA.'],['Complete removal of host acetylcholine receptors','The described target is an invertebrate chloride channel, not all host receptors.']], 'Predict reduced excitability from increased invertebrate chloride conductance.'),
q('Pharmacology','General Principles','Praziquantel calcium permeability','A trematode exposed to praziquantel rapidly contracts and develops tegumental injury. Which early ionic effect is most closely associated with its action?', 'Increased parasite calcium permeability', 'Praziquantel increases calcium permeability in susceptible parasites, producing contraction and associated surface injury. The effect differs from the flaccid paralysis produced by increased inhibitory chloride conductance and from slower disruption of microtubule-dependent metabolism.', [['Loss of calcium entry with immediate relaxation','The characteristic early response is increased calcium-associated contraction.'],['Inhibition of bacterial RNA polymerase','Trematode contraction is not explained by an antibacterial transcription target.'],['Blockade of fungal sterol demethylation','A fungal sterol enzyme does not account for this worm response.']], 'Connect praziquantel-associated contraction with altered parasite calcium permeability.'),
q('Pharmacology','General Principles','Pyrantel depolarizing blockade','An intestinal nematode is immobilized by sustained activation of its nicotinic cholinergic receptors after pyrantel exposure. Which neuromuscular mechanism is demonstrated?', 'Persistent depolarizing blockade', 'Pyrantel stimulates susceptible helminth nicotinic receptors and causes sustained depolarization with paralysis. Initial receptor activation can therefore end in impaired movement, differing from competitive receptor antagonism or direct microtubule disruption.', [['Competitive blockade without receptor activation','The stem describes receptor stimulation rather than simple competitive antagonism.'],['Glutamate-gated chloride hyperpolarization','That inhibitory chloride mechanism is associated with ivermectin.'],['Sterol-dependent membrane pore formation','That describes a polyene antifungal interaction rather than cholinergic paralysis.']], 'Distinguish sustained depolarizing helminth paralysis from inhibitory-channel paralysis.'),
q('Pharmacology','General Principles','Mupirocin tRNA charging','Bacterial protein synthesis stops after a topical antibiotic inhibits isoleucyl-tRNA synthetase. Which substrate is most directly depleted for translation?', 'Transfer RNA charged with isoleucine', 'Mupirocin inhibits bacterial isoleucyl-tRNA synthetase, preventing attachment of isoleucine to its cognate transfer RNA. Ribosomes may remain structurally intact but cannot sustain translation without the required charged tRNA, localizing the block before peptide-bond formation.', [['Messenger RNA bearing a polyadenylate tail','The targeted enzyme charges tRNA rather than modifying messenger RNA tails.'],['UDP-linked peptidoglycan sugars','Wall sugar precursors are not made by an aminoacyl-tRNA synthetase.'],['Fungal ergosterol molecules','A bacterial tRNA charging enzyme does not synthesize fungal sterols.']], 'Locate antimicrobial inhibition at aminoacyl-tRNA charging upstream of ribosomal elongation.'),
q('Pharmacology','General Principles','Beta lactamase inhibitor protection','A bacterial enzyme hydrolyzes an aminopenicillin before it reaches its target. Addition of a susceptible beta-lactamase inhibitor restores activity. What is the inhibitor doing?', 'Protecting the antibiotic from enzymatic destruction', 'A beta-lactamase inhibitor can preserve a partner beta-lactam by inhibiting the enzyme that would hydrolyze it. Restoration depends on the particular enzyme and inhibitor; this does not guarantee activity against altered penicillin-binding proteins or every beta-lactamase.', [['Rebuilding an absent bacterial cell wall','An inhibitor cannot create a target in an organism that lacks a wall.'],['Replacing every altered penicillin-binding protein','Enzyme inhibition does not repair altered antibiotic target proteins.'],['Converting the partner drug into a ribosomal inhibitor','Protection from hydrolysis does not change its target into a ribosome.']], 'Distinguish protection from drug destruction from correction of target-mediated resistance.'),
q('Pharmacology','General Principles','Postantibiotic growth suppression','After a brief antibiotic exposure, a culture is washed until free drug is below its inhibitory concentration. Bacterial regrowth remains delayed. Which phenomenon is demonstrated?', 'Postantibiotic effect', 'The postantibiotic effect is persistent suppression of microbial growth after effective drug exposure has ended. It can reflect lingering cellular injury or recovery requirements and is distinct from continued inhibition solely because extracellular drug remains above the measured MIC.', [['A lower minimum bactericidal concentration by definition','Delayed regrowth after washout does not itself measure the bactericidal concentration.'],['Proof that every surviving bacterium is permanently resistant','Delayed growth is not evidence of stable inherited resistance.'],['Continuous extracellular concentrations above the MIC','The experiment explicitly places free drug below the inhibitory concentration.']], 'Recognize persistent microbial growth suppression after antibiotic removal.', 'pharm','recognition'),
q('Microbiology','General Principles','Segment reassortment','Two distinct influenza A strains infect one cell. Some progeny contain entire RNA segments from each parent rather than small sequence patches within one segment. Which genetic process produced these genomes?', 'Reassortment of segmented viral genomes', 'Reassortment exchanges complete genome segments during coinfection by compatible segmented viruses. It can produce abrupt combinations of viral properties. Recombination instead involves exchange within nucleic acid molecules, while point mutation changes individual nucleotides.', [['Point mutation at one nucleotide','A single-base substitution cannot exchange entire parental genome segments.'],['Bacterial conjugation','Pilus-mediated plasmid transfer is a bacterial process rather than influenza segment mixing.'],['Reverse transcription','Copying RNA into DNA does not explain exchange of intact influenza RNA segments.']], 'Distinguish intact viral genome segment exchange from mutation or intramolecular recombination.','influenza'),
q('Microbiology','General Principles','Viral complementation','A viral mutant cannot make a capsid protein. During coinfection, a second virus supplies that protein and permits particle production, but isolated mutant progeny still have the original defective gene. What occurred?', 'Complementation by a protein supplied in trans', 'Complementation restores a missing function through a product made by another genome in the same cell. It need not repair the defective genome. Continued dependence on coinfection therefore distinguishes complementation from a heritable genetic correction.', [['Stable repair of the mutant genome by definition','The original genetic defect remains present in the resulting mutant progeny.'],['Reassortment of every viral genome','Supplying a protein does not require exchange of genome segments.'],['A stable back-mutation restoring the capsid gene','A back-mutation would correct the gene, unlike the persisting defect described here.']], 'Separate transient functional rescue from heritable correction of a viral genome.','micro','integration'),
q('Microbiology','General Principles','Phenotypic mixing surface coat','A virus grown in a doubly infected cell acquires a surface glycoprotein encoded by the other virus. Its genome remains unchanged, and the next generation loses the altered entry phenotype. Which process fits?', 'Phenotypic mixing of virion components', 'Phenotypic mixing can give a particle structural proteins supplied by a coinfecting virus without changing the packaged genome. The altered entry behavior is therefore transient and may disappear after one cycle, unlike a stable change encoded in the viral nucleic acid.', [['Permanent antigenic mutation of the genome','Unchanged nucleic acid and loss after one cycle argue against a stable mutation.'],['Prophage integration into bacterial DNA','The described event concerns surface proteins of animal viruses.'],['Selection of a new host chromosome allele','Virion coating does not require a genetic change in the host chromosome.']], 'Infer transient virion phenotype transfer from unchanged genome and single-cycle persistence.','micro','integration'),
q('Microbiology','General Principles','Viral eclipse period','After a virus enters cultured cells, no infectious particles can initially be recovered even after the cells are disrupted. Infectious intracellular particles appear later before extracellular release. What is the initial interval called?', 'Eclipse period', 'The eclipse period follows entry and uncoating, when intact infectious virions are absent while components are being produced. It ends as infectious particles assemble inside cells. This differs from the broader latent interval measured before extracellular progeny become detectable.', [['Incubation period of clinical illness','Clinical symptom timing is not the intracellular infectivity interval measured here.'],['Persistent extracellular release phase','The experiment initially detects no infectious particles, including inside disrupted cells.'],['Bacterial exponential growth phase','The assay describes virion disassembly and assembly rather than bacterial cell division.']], 'Distinguish intracellular eclipse from the interval preceding extracellular viral release.','micro','recognition'),
q('Microbiology','General Principles','Poxvirus cytoplasmic replication','A large DNA virus produces replication factories entirely in the cytoplasm. Which feature most directly permits it to transcribe genes without nuclear host RNA polymerase?', 'Virion-associated viral transcription enzymes', 'Poxviruses carry machinery needed for early transcription and encode extensive replication functions, supporting cytoplasmic replication. Most DNA viruses rely more heavily on nuclear processes, so the location creates a specific requirement for viral transcriptional capacity.', [['Dependence on nuclear host polymerase at every early step','Exclusive cytoplasmic factories cannot directly use a polymerase confined to the nucleus.'],['Absence of a DNA genome','The stem identifies a DNA virus; cytoplasmic replication does not imply an RNA genome.'],['Use of bacterial ribosomes inside the virion','Poxviruses use host translation machinery rather than carrying bacterial ribosomes.']], 'Connect cytoplasmic DNA-virus replication with a requirement for viral transcription machinery.'),
q('Microbiology','General Principles','Influenza nuclear transcription','An RNA virus replicates through a nuclear phase and acquires capped primers from host transcripts. Which feature distinguishes influenza from many cytoplasmically replicating RNA viruses?', 'Use of host nuclear RNA processing resources for viral transcription', 'Influenza viral ribonucleoproteins enter the nucleus, where viral transcription uses capped fragments derived from host RNA. An RNA genome therefore does not guarantee a wholly cytoplasmic life cycle; replication location depends on the requirements of the particular virus.', [['An obligatory integrated DNA provirus','Influenza does not normally replicate through an integrated DNA stage.'],['A requirement for bacterial transcription enzymes','Influenza infects animal cells and uses its own polymerase with host RNA resources.'],['A genome made entirely of double-stranded DNA','Nuclear entry does not change the influenza genome into a DNA genome.']], 'Explain why an RNA virus can require a nuclear phase without a DNA intermediate.'),
q('Microbiology','General Principles','Reovirus intraparticle transcription','A double-stranded RNA virus retains its genome within a core particle while producing messenger RNA. Which virion component is necessary because host cells cannot directly transcribe its genome?', 'RNA-dependent RNA polymerase', 'Reoviruses bring an RNA-dependent RNA polymerase that transcribes messenger RNA from their double-stranded RNA genome. Transcription within a core also limits exposure of the genome. Host DNA-dependent polymerases cannot substitute for this RNA-template activity.', [['Host DNA ligase packaged as the viral transcriptase','DNA ligase joins breaks and does not transcribe a double-stranded RNA template.'],['A bacterial cell-wall transpeptidase','Wall cross-linking cannot produce messenger RNA from viral RNA.'],['Viral neuraminidase alone','Sialic-acid cleavage cannot replace the required RNA polymerase activity.']], 'Identify the transcription machinery required by a double-stranded RNA genome.'),
q('Microbiology','General Principles','Poliovirus polyprotein processing','A positive-sense RNA viral genome is translated into a long precursor containing structural and enzymatic regions. What step is necessary to generate the separate mature viral proteins?', 'Proteolytic cleavage of the viral polyprotein', 'Picornaviruses such as poliovirus encode a polyprotein that is cut by viral proteases into functional products. A single translated precursor can therefore yield multiple proteins without separate monocistronic transcripts for each mature product.', [['Host removal of all coding exons','Removing coding exons would not produce the normal set of mature viral proteins.'],['Integration into a bacterial chromosome','Poliovirus replication does not require bacterial DNA integration.'],['Separate transcription of every mature protein as an independent gene','The observed single polyprotein is processed after translation rather than requiring an independent transcript for each product.']], 'Explain production of multiple mature picornaviral proteins from one translated precursor.'),
q('Microbiology','General Principles','Coronavirus discontinuous transcription','A coronavirus-infected cell contains a nested group of shorter messenger RNAs sharing common terminal sequences. Which viral strategy explains expression of multiple downstream genes?', 'Production of subgenomic messenger RNAs', 'Coronaviruses generate subgenomic RNAs that permit expression of genes beyond the initial replicase region. Their nested RNA products reflect a regulated viral transcription strategy rather than host chromosomal splicing of an integrated coronavirus provirus.', [['Obligatory integration followed by host DNA splicing','Coronavirus replication does not require an integrated DNA stage.'],['Independent replication of each RNA as a separate genome segment','The shorter messenger RNAs are subgenomic transcripts rather than a set of independently packaged genome segments.'],['Proteolytic cleavage of the RNA into mature proteins','RNA cleavage cannot itself produce proteins; downstream genes require translatable messenger RNAs.']], 'Recognize subgenomic RNA production as a coronavirus gene-expression strategy.'),
q('Microbiology','General Principles','Coronavirus proofreading exonuclease','A large RNA virus encodes an exonuclease that can remove mismatched nucleotides during replication. Which consequence is most directly supported by this activity?', 'Improved fidelity of viral RNA synthesis', 'Coronavirus proofreading activity can correct some replication errors and supports maintenance of a relatively large RNA genome. It reduces, rather than abolishes, mutation; recombination and remaining copying errors still permit viral evolution.', [['Guaranteed absence of all future viral mutations','Proofreading reduces errors but cannot eliminate every source of genetic variation.'],['Conversion of the RNA genome into a segmented DNA genome','Exonuclease proofreading does not change genome material or segmentation.'],['Elimination of the need for RNA-dependent RNA polymerase','Proofreading assists copying fidelity but does not replace the enzyme that synthesizes viral RNA.']], 'Infer the effect and limits of proofreading during viral RNA replication.'),
q('Microbiology','General Principles','Parvovirus S phase dependence','A small single-stranded DNA virus replicates best in rapidly dividing erythroid precursors and lacks its own complete DNA replication machinery. Which host state most directly supports its replication?', 'Availability of host DNA synthesis functions during S phase', 'Parvoviruses depend strongly on host DNA synthetic machinery and favor suitable dividing cells. Erythroid precursor infection can impair red-cell production. This dependence differs from a virus that encodes a more autonomous replication system and can replicate in nondividing cells.', [['Permanent shutdown of host nucleotide synthesis','A DNA virus requiring host synthesis machinery would not benefit from its shutdown.'],['Loss of every host DNA polymerase','Removing the required host enzymes would impair viral replication.'],['Differentiation into a nucleus-free mature erythrocyte','Mature erythrocytes lack the nuclear machinery needed for productive replication.']], 'Connect small DNA-virus replication dependence with actively cycling host precursors.'),
q('Microbiology','Hematology','Parvovirus transient aplastic crisis','A person with chronic hemolysis abruptly develops severe anemia and nearly absent reticulocytes after a febrile illness. Parvovirus B19 is detected. Which cell population is directly impaired?', 'Erythroid precursors in bone marrow', 'Parvovirus B19 infects erythroid precursors and can transiently interrupt red-cell production. Patients whose red cells already have shortened survival can become markedly anemic during this pause. Reticulocytopenia localizes the immediate problem to production rather than compensatory erythropoiesis.', [['Mature erythrocytes undergoing increased division','Mature erythrocytes do not divide and are not the productive precursor target.'],['Platelets as the exclusive viral replication site','The characteristic marrow target underlying this syndrome is the erythroid precursor.'],['Renal tubules producing excess erythropoietin','Increased erythropoietin alone would not explain selective precursor infection and low reticulocytes.']], 'Integrate short red-cell survival and reticulocytopenia to locate parvovirus marrow injury.','micro','integration'),
q('Microbiology','General Principles','HBV partial genome repair','An incoming hepatitis B genome contains relaxed circular DNA with an incomplete strand. Which nuclear form serves as the persistent transcription template after repair?', 'Covalently closed circular DNA', 'Host repair converts incoming hepatitis B relaxed circular DNA into nuclear covalently closed circular DNA. This episomal template produces viral RNAs. It is distinct from integrated fragments, which are not required as the normal template for the complete replication cycle.', [['Unrepaired relaxed circular DNA used directly as a fully intact template','The incoming genome must be repaired to the covalently closed circular nuclear template.'],['A double-stranded RNA genome retained permanently','HBV stores its persistent transcription template as DNA, not double-stranded RNA.'],['A host chromosome with every viral copy integrated','Integration can occur but is not required for the normal HBV replication template.']], 'Identify the repaired nuclear HBV DNA reservoir used for viral transcription.'),
q('Microbiology','General Principles','Hepatitis D helper envelope','Hepatitis D RNA replicates in a cell, but infectious particles cannot be released without a hepatitis B surface protein. What does hepatitis B provide to the defective virus?', 'Envelope proteins needed for infectious particle formation', 'Hepatitis D depends on hepatitis B surface antigen for its envelope and productive transmission. This helper relationship does not mean hepatitis B supplies the hepatitis D RNA genome or that hepatitis D is simply a mutant form of the hepatitis B DNA genome.', [['The complete hepatitis D RNA sequence as hepatitis B DNA','The viruses have distinct genomes rather than one being the full sequence of the other.'],['Reverse transcriptase that copies the hepatitis D RNA into DNA','Hepatitis D replication does not require a hepatitis B-supplied reverse transcription stage.'],['A host ribosome packaged as the only missing component','The defining helper function is provision of envelope proteins.']], 'Explain hepatitis D dependence on hepatitis B through envelope acquisition.'),
q('Microbiology','General Principles','HIV diploid RNA template switching','A retroviral particle contains two related RNA genome copies. During reverse transcription, the polymerase switches between them, yielding a mosaic DNA sequence. Which outcome is promoted?', 'Genetic recombination between the copackaged RNA genomes', 'Retroviral reverse transcriptase can switch templates while copying the two packaged RNA molecules. The resulting DNA may combine parental sequences. This intramolecular mosaic differs from exchanging whole separate genome segments by reassortment.', [['Reassortment of influenza-like genome segments','HIV has two RNA copies rather than an influenza-like set of distinct segments.'],['Bacterial transformation with naked chromosomal DNA','The event occurs during reverse transcription inside a retroviral replication cycle.'],['Protein-only inheritance without nucleic acid change','The mosaic sequence is a heritable nucleic acid change rather than a transient protein coat.']], 'Connect retroviral copackaging and template switching with genetic recombination.'),
q('Microbiology','General Principles','HPV E6 p53 disruption','A high-risk papillomavirus protein recruits a host ubiquitin ligase and promotes degradation of p53. Which cellular defense is most directly weakened?', 'DNA-damage-associated cell-cycle arrest and apoptosis', 'High-risk HPV E6 can promote p53 degradation, weakening responses that normally restrain damaged cells or trigger apoptosis. This contributes to oncogenesis but does not imply that infection alone inevitably produces cancer; persistence and additional factors matter.', [['E2F release through direct retinoblastoma binding','Retinoblastoma disruption is associated with E7 and is distinct from E6-mediated p53 degradation.'],['Direct viral RNA proofreading','p53 is a host tumor suppressor rather than the viral proofreading enzyme.'],['Mismatch repair through obligatory removal of MSH2','The described ubiquitin-mediated target is p53, not an obligatory loss of MSH2.']], 'Infer the host defense lost when a viral protein promotes p53 degradation.'),
q('Microbiology','General Principles','HPV E7 retinoblastoma release','A high-risk papillomavirus protein binds retinoblastoma protein and releases E2F transcription factors. Which cellular program becomes less restrained?', 'Progression from G1 into S phase', 'Retinoblastoma protein normally limits E2F-dependent expression of genes needed for S phase. High-risk HPV E7 disrupts that restraint, promoting a replication-permissive cell-cycle state. This mechanism differs from E6-mediated interference with p53.', [['Exit from mitosis through destruction of viral capsids','Retinoblastoma-E2F regulation principally controls the G1-to-S transition.'],['Mitochondrial oxidation of fatty acids only','The stated interaction is a cell-cycle regulatory event rather than a specific metabolic enzyme block.'],['Activation of caspases as the principal result of E2F release','Loss of retinoblastoma restraint promotes S-phase gene expression rather than directly defining executioner caspase activation.']], 'Map viral disruption of retinoblastoma-E2F binding to G1-to-S progression.'),
q('Microbiology','General Principles','EBV CD21 attachment','An enveloped virus uses its gp350 glycoprotein to attach to the complement receptor CD21 on B lymphocytes. Which virus most characteristically uses this attachment interaction?', 'Epstein-Barr virus', 'Epstein-Barr virus attachment to B cells involves gp350 binding to CD21, also called complement receptor 2. This receptor association helps explain B-cell tropism, although successful infection requires additional entry steps and cannot be inferred from receptor binding alone.', [['HIV using CD21 as its defining entry receptor','HIV characteristically uses CD4 and appropriate coreceptors rather than this gp350-CD21 interaction.'],['Influenza using gp350','Influenza uses its hemagglutinin to recognize sialylated structures.'],['Poliovirus using a herpesviral gp350 envelope','Poliovirus is nonenveloped and does not use the EBV envelope glycoprotein.']], 'Recognize the EBV gp350-CD21 attachment pair.','micro','recognition'),
q('Microbiology','General Principles','Measles syncytium formation','A respiratory virus causes infected cells to fuse with nearby cells into multinucleated syncytia. Which viral surface function directly permits this cytopathic effect?', 'Membrane fusion activity expressed on infected cells', 'Fusion proteins on infected cell surfaces can join adjacent host membranes, creating multinucleated syncytia. Paramyxoviruses such as measles illustrate this mechanism. The phenomenon is a membrane event rather than evidence that nuclei divide without any viral surface contribution.', [['Bacterial conjugative pilus extension','Animal cell syncytia do not result from bacterial plasmid-transfer pili.'],['Removal of all host plasma membranes by DNA ligase','DNA ligase does not catalyze membrane fusion.'],['Viral polymerase joining nuclear DNA molecules','Joining nucleic acid cannot directly merge adjacent plasma membranes into a syncytium.']], 'Connect viral cell-surface fusion proteins with multinucleated syncytium formation.'),
q('Microbiology','Nervous System','Rabies retrograde neural spread','After inoculation into a peripheral wound, a neurotropic virus reaches the central nervous system through peripheral nerves. Which intracellular transport direction is most relevant?', 'Retrograde axonal transport toward neuronal cell bodies', 'Rabies virus can enter peripheral nerves and move toward neuronal cell bodies by retrograde transport before spreading through the nervous system. This mechanism explains neural spread without requiring the virus to circulate freely in blood at high levels throughout the incubation period.', [['Anterograde movement away from the cell body as the initial inward route','Movement from a peripheral terminal toward the central nervous system requires retrograde transport.'],['Exclusive transport within mature erythrocytes','Rabies neural invasion is not mediated by replication inside mature red cells.'],['Passive flow within the intestinal lumen','The exposure and central spread are linked by peripheral nerves rather than the intestinal lumen.']], 'Infer the axonal transport direction needed for inward rabies neural spread.'),
q('Microbiology','General Principles','Viral receptor tropism constraint','A cultured cell supports viral genome replication when viral nucleic acid is experimentally introduced, but intact virions cannot infect it. The cell lacks the known attachment receptor. What step is limiting?', 'Receptor-dependent viral entry', 'Experimental nucleic acid delivery bypasses the normal entry pathway. Successful replication after that bypass indicates that intracellular machinery can support the genome, while failure of intact particles identifies a barrier at attachment or entry rather than an absolute inability to replicate.', [['An absolute inability of the genome to replicate in the cell','Replication after experimental genome introduction contradicts that interpretation.'],['Universal absence of functional host ribosomes','Production after nucleic acid introduction requires adequate host translation machinery.'],['A defect exclusively in release of completed particles','Failure of initial intact-virion infection and a missing receptor point upstream of release.']], 'Use experimental entry bypass to separate receptor restriction from intracellular replication restriction.','micro','integration'),
q('Microbiology','General Principles','Defective interfering particles','A high-multiplicity viral preparation contains shortened genomes that replicate only with helper virus and reduce production of standard virus. Which explanation best fits?', 'Defective interfering genomes compete for shared replication resources', 'Defective interfering particles lack functions required for autonomous infection but can exploit helper-virus products. Their genomes may compete with standard genomes for replication or packaging, reducing standard-virus yield without functioning as independent fully competent viruses.', [['Every shortened genome is fully autonomous by definition','Helper dependence directly contradicts autonomous replication.'],['Neutralizing antibody carried as the shortened viral genome','An antibody is not a shortened viral nucleic acid genome dependent on helper replication products.'],['Guaranteed repair of every helper-virus genome','Defective genome interference reduces standard-virus production and does not guarantee genetic repair.']], 'Explain helper-dependent viral interference through competition by defective genomes.'),
q('Microbiology','General Principles','Plaque assay infectious units','A diluted virus preparation produces discrete clear areas in a susceptible cell monolayer under a semisolid overlay. What does counting these areas estimate?', 'Plaque-forming infectious units under the assay conditions', 'A plaque assay estimates infectious units capable of initiating localized spread in the tested cells. It does not count every physical particle or genome, because damaged or noninfectious particles may be present and cellular susceptibility affects the result.', [['The exact count of all viral genomes regardless of infectivity','Genome assays can detect noninfectious material that does not form plaques.'],['Total concentration of viral envelope protein alone','Protein abundance does not establish the ability to initiate productive localized infection.'],['Number of bacterial colonies growing without host cells','The assay uses susceptible host-cell monolayers rather than bacteria on nutrient agar.']], 'Distinguish an infectivity-based plaque count from physical particle or genome counts.','micro','recognition'),
q('Microbiology','General Principles','Neutralization versus binding antibody','Two antibodies bind a viral surface protein equally in an immunoassay, but only one prevents infection in cell culture. Which additional function defines the protective in-vitro effect?', 'Interference with a step required for productive infection', 'Neutralizing antibodies block a function needed for infection, such as receptor engagement or fusion. Binding alone does not establish neutralization, because antibodies can recognize exposed epitopes without disabling an essential step. An in-vitro result also does not establish clinical protection by itself.', [['Any detectable binding guarantees neutralization','The comparison explicitly shows similar binding with different infection outcomes.'],['Required cleavage of all viral DNA by the antibody','Antibodies can neutralize by entry blockade without enzymatically cleaving genomes.'],['Unchanged receptor engagement and fusion despite infection blockade being impossible','Neutralization can act at other required steps, so preserved binding alone does not rule out functional inhibition.']], 'Separate antigen binding from functional neutralization of viral infectivity.'),
q('Microbiology','General Principles','Persistent infection versus latency','A culture continuously releases small amounts of infectious virus for weeks while most cells remain viable. Which pattern best describes this observation rather than true transcriptionally restricted latency?', 'Persistent productive infection', 'Persistent productive infection includes continuing production of progeny over an extended interval. Latency instead involves a more restricted genome state with no ongoing complete productive cycle until reactivation. Cell survival alone cannot distinguish these states; infectious output is the key observation.', [['Complete absence of productive replication','Continuous release of infectious progeny contradicts this interpretation.'],['Sterilizing clearance of all viral genomes','Ongoing infectious output indicates that viral genetic material remains.'],['A noninfectious antibody response alone','Antibodies cannot explain continuous production of new infectious viral particles.']], 'Use continued infectious output to distinguish persistence from nonproductive latency.'),
q('Microbiology','Gastrointestinal','Giardia infective cyst','After drinking untreated stream water, a camper develops persistent greasy stools. Giardia trophozoites are found in a duodenal sample. Which form most likely survived outside the host and initiated infection?', 'Mature cyst ingested in contaminated water', 'Giardia cysts tolerate environmental conditions and initiate infection after ingestion. Excystation releases trophozoites that colonize the proximal intestine. Identifying the transmitted stage differs from merely identifying the motile form visible at the intestinal site of disease.', [['Filariform larva penetrating bare skin','That stage characterizes several nematodes rather than Giardia transmission.'],['Sporozoite injected by a mosquito','Mosquito inoculation is associated with malaria rather than intestinal giardiasis.'],['Cercaria entering through intact skin','Cercarial penetration is a schistosome route rather than a Giardia route.']], 'Distinguish the environmentally transmitted Giardia cyst from the intestinal trophozoite.','giardia'),
q('Microbiology','Gastrointestinal','Cryptosporidium immediate infectivity','Several people acquire watery diarrhea through direct contact with an infected child. Cryptosporidium oocysts are identified. Which feature of the shed oocysts permits rapid person-to-person spread?', 'They are already sporulated and infectious when excreted', 'Cryptosporidium oocysts can be infectious when passed, allowing direct fecal-oral transmission without a prolonged maturation period in soil. This differs from parasites whose freshly shed stages must develop externally before they become infectious.', [['A required month of maturation in dry soil','A prolonged obligatory soil maturation phase would limit the immediate transmission described.'],['An obligatory snail intermediate host','Cryptosporidium transmission does not require development in a snail.'],['Development into a blood-feeding adult worm','Cryptosporidium is a protozoan rather than a helminth producing adult worms.']], 'Explain rapid fecal-oral transmission through infectivity of newly shed Cryptosporidium oocysts.','crypto'),
q('Microbiology','General Principles','Schistosome cercarial penetration','A traveler develops schistosomiasis after swimming in freshwater containing infected snails. Which parasite stage leaves the snail and directly enters human skin?', 'Free-swimming cercaria', 'Schistosome cercariae emerge from infected snails and penetrate skin during freshwater contact. They develop into schistosomula after entry. Eggs instead leave the human host, while miracidia infect the snail, so those stages occupy different directions of the cycle.', [['Miracidium that normally infects the snail','Miracidia move from hatched eggs into snails rather than directly initiating human infection.'],['Embryonated egg swallowed with pork','Schistosomiasis is acquired through cercarial skin penetration rather than pork-associated egg ingestion.'],['Adult worm released into the water','Adult schistosomes live in host blood vessels rather than being the swimming infective stage.']], 'Identify the snail-derived schistosome stage that penetrates human skin.','schistosoma','recognition'),
q('Microbiology','Gastrointestinal','Schistosome egg granulomatous fibrosis','A person with chronic intestinal schistosomiasis develops periportal fibrosis and portal hypertension. Which parasite-related event principally drives the local inflammatory fibrosis?', 'Host granulomatous responses around retained eggs', 'Many schistosome eggs become trapped in tissues rather than being excreted. Host inflammatory responses around these eggs promote granuloma formation and fibrosis. Adult worms reside within vessels, but their physical presence alone does not explain the characteristic egg-centered tissue lesions.', [['Direct occupation of every bile duct by adult worms','Egg-centered inflammation rather than universal bile-duct occupation explains the described fibrosis.'],['A viral provirus integrated into hepatocytes','Schistosoma is a helminth, not an integrating virus.'],['An isolated loss of pancreatic digestive enzymes','Pancreatic enzyme deficiency does not explain periportal egg granulomas.']], 'Connect retained schistosome eggs with granulomatous periportal fibrosis.','schistosoma'),
q('Microbiology','Renal','Urinary schistosomiasis squamous injury','A patient from an endemic region has chronic terminal hematuria, bladder-wall calcification, and Schistosoma haematobium eggs in urine. Which malignancy is classically associated with this chronic injury?', 'Squamous cell carcinoma of the bladder', 'Chronic urinary schistosomiasis produces egg-associated inflammation and tissue injury that is linked to bladder squamous cell carcinoma. This is an association with a particular inflammatory exposure, not a claim that every infected patient develops cancer or that all bladder cancers are squamous.', [['Renal clear-cell carcinoma as the characteristic bladder lesion','Clear-cell renal carcinoma arises in kidney tissue rather than representing this classic bladder association.'],['Wilms tumor of early childhood','A childhood embryonal renal tumor is not the characteristic chronic schistosomal bladder malignancy.'],['Prostatic acinar adenocarcinoma','That cancer arises from prostate glands rather than the chronically injured bladder squamous epithelium.']], 'Associate chronic S haematobium bladder inflammation with squamous malignancy.','schistosoma'),
q('Microbiology','General Principles','Strongyloides autoinfection persistence','A patient develops strongyloidiasis decades after leaving an endemic region, with no subsequent exposure. Which life-cycle property best explains persistence over this interval?', 'Larvae can become infective within the host and reinvade tissues', 'Strongyloides stercoralis can sustain an autoinfective cycle in which larvae develop into infective forms and penetrate intestinal mucosa or perianal skin. Repeated internal cycles allow prolonged infection without a new external exposure or survival of one adult worm for the entire interval.', [['An obligatory new mosquito bite each generation','Autoinfection does not require repeated mosquito inoculation.'],['Dormant liver hypnozoites identical to malaria','Strongyloides persistence uses larval autoinfection rather than a Plasmodium liver stage.'],['Reinfection only after eating undercooked fish','The absence of new exposure is explained by an internal cycle, not obligatory fish ingestion.']], 'Explain decades-long Strongyloides persistence through an internal autoinfection cycle.','strongyloides'),
q('Microbiology','General Principles','Strongyloides steroid hyperinfection','A patient with previously silent Strongyloides infection receives high-dose glucocorticoids and develops numerous larvae in sputum with enteric gram-negative sepsis. Which process best unifies the findings?', 'Accelerated autoinfection with increased larval migration and bacterial dissemination', 'Glucocorticoid exposure can permit Strongyloides hyperinfection with extensive larval migration along the usual intestinal-pulmonary route. Enteric bacteria can disseminate in this setting. The combined larval burden and bacterial sepsis are not explained by isolated allergy or uncomplicated intestinal colonization.', [['Bacterial sepsis unrelated to the increase in migrating larvae','The conjunction of hyperinfection and enteric sepsis is explained by increased migration and associated bacterial dissemination.'],['Complete sterilization of an old infection by glucocorticoids','The increased larval burden indicates worsening infection rather than clearance.'],['Relapse from dormant malaria liver stages','Malaria hypnozoites do not generate nematode larvae in sputum.']], 'Integrate steroid exposure, pulmonary larvae and enteric sepsis as Strongyloides hyperinfection.','strongyloides','integration'),
q('Microbiology','General Principles','Malaria mosquito inoculum','An infected Anopheles mosquito introduces malaria parasites into a person. Which stage first travels to the liver before the symptomatic erythrocytic cycle begins?', 'Sporozoite', 'Mosquitoes inoculate sporozoites, which infect hepatocytes and develop before releasing blood-invasive merozoites. Gametocytes are instead taken up by mosquitoes, so identifying a blood-smear stage does not automatically identify the form injected into a new human host.', [['Gametocyte','Gametocytes in human blood are acquired by mosquitoes rather than serving as the usual injected stage.'],['Merozoite','Merozoites released from tissue schizonts invade erythrocytes after the initial liver stage.'],['Ookinete','Ookinetes develop in the mosquito and are not the stage injected into humans.']], 'Identify the mosquito-inoculated Plasmodium stage preceding liver infection.','malaria','recognition'),
q('Microbiology','General Principles','Malaria hypnozoite relapse','A person with previously treated Plasmodium vivax malaria has recurrent parasitemia months later without new mosquito exposure. Which dormant reservoir can account for true relapse?', 'Hypnozoites within hepatocytes', 'Plasmodium vivax and P ovale can leave dormant hepatic forms called hypnozoites. Later activation can seed a new blood-stage infection without reinfection. This differs from recrudescence caused by persistence of inadequately cleared erythrocytic parasites.', [['Persistent gametocytes multiplying inside the spleen','Gametocytes do not provide the dormant liver reservoir responsible for vivax relapse.'],['Bacterial endospores within erythrocytes','Plasmodium is a protozoan and does not form bacterial endospores.'],['Mosquito-stage ookinetes within renal tubules','Ookinetes are mosquito stages rather than dormant human renal stages.']], 'Distinguish hepatic hypnozoite relapse from persistence of blood-stage malaria.','malaria'),
q('Microbiology','Cardiovascular','Falciparum erythrocyte sequestration','A patient with falciparum malaria develops severe microvascular dysfunction despite a peripheral smear that does not display all mature infected erythrocytes. Which property helps explain both findings?', 'Adhesion of infected erythrocytes to vascular endothelium', 'Falciparum-infected erythrocytes can express surface proteins that promote endothelial adhesion and sequestration in small vessels. This reduces circulation of some mature stages and contributes to organ dysfunction, linking an apparently incomplete peripheral picture with significant tissue parasite burden.', [['Universal confinement of all parasites to hepatocytes','Blood-stage falciparum disease involves erythrocytes rather than exclusive liver confinement.'],['Exclusive destruction of erythrocytes in the spleen without endothelial adhesion','Splenic removal alone does not explain tissue sequestration of mature infected cells.'],['Failure of all parasites to enter erythrocytes','The microvascular process depends on infected erythrocytes being present.']], 'Integrate peripheral stage distribution and organ dysfunction through infected-cell cytoadherence.','malaria','integration'),
q('Microbiology','Nervous System','Cysticercosis egg ingestion','A vegetarian who has never eaten pork develops brain cysticerci due to Taenia solium. Which exposure can produce this tissue infection despite the dietary history?', 'Ingestion of eggs shed by a human intestinal tapeworm carrier', 'Human cysticercosis follows ingestion of T solium eggs, usually through fecal contamination. Larvae then invade tissues. Eating pork containing cysticerci instead produces intestinal taeniasis, so absence of pork ingestion does not exclude the egg-mediated tissue infection.', [['Ingestion of pork cysticerci as the required cause of brain cysts','Pork cysticerci produce the intestinal adult stage rather than directly causing tissue cysticercosis.'],['Cercariae penetrating skin during swimming','That exposure belongs to schistosomiasis rather than the T solium cycle.'],['An infected Anopheles mosquito bite','Mosquito inoculation does not transmit T solium eggs or cysticerci.']], 'Distinguish fecal-oral T solium egg transmission from meat-associated intestinal taeniasis.','cysticercosis'),
q('Microbiology','Gastrointestinal','Echinococcus accidental intermediate host','A person exposed to dog feces develops a hepatic hydatid cyst. Which role does the human occupy in the Echinococcus granulosus life cycle?', 'Accidental intermediate host harboring larval cysts', 'Humans can ingest Echinococcus eggs from an infected canid source and develop larval hydatid cysts in tissues. Dogs and other canids harbor the adult intestinal stage. Humans therefore function as accidental intermediate hosts rather than the usual definitive host producing eggs.', [['Definitive host with obligatory adult intestinal worms','Human hydatid disease is caused by tissue larvae rather than the usual canid adult stage.'],['Arthropod vector injecting sporozoites','A human with hydatid cysts is not a vector and the parasite is a cestode.'],['Snail host releasing cercariae','Snail development and cercariae are trematode features rather than this cestode cycle.']], 'Assign the human host role from the tissue larval stage of echinococcosis.','echinococcus'),
q('Microbiology','Musculoskeletal','Trichinella muscle larvae','After eating incompletely cooked wild boar, several diners develop fever, myalgia, periorbital edema and eosinophilia. A muscle specimen contains encysted nematode larvae. Which tissue phase explains the muscle symptoms?', 'Trichinella larvae establishing nurse-cell complexes in skeletal muscle', 'Trichinella infection begins after ingestion of larvae in meat, followed by intestinal maturation and dissemination of newborn larvae to striated muscle. The muscle phase explains myalgia and inflammatory findings; adult worms do not normally live inside muscle fibers.', [['Adult hookworms feeding in skeletal muscle','Hookworm adults reside in the intestine rather than forming the described muscle cysts.'],['Schistosome eggs maturing into adult worms within myocytes','Schistosome adults occupy vessels and do not develop from eggs inside skeletal muscle.'],['Malaria gametocytes encysting within muscle','Malaria gametocytes are blood stages rather than tissue nematode larvae.']], 'Connect a meat-associated systemic illness with the Trichinella skeletal-muscle larval phase.','trichinella','integration'),
q('Microbiology','Hematology','Leishmania macrophage amastigote','A patient with prolonged fever and splenomegaly has macrophages containing small intracellular organisms with a nucleus and kinetoplast. Which parasite form replicates within these human phagocytes?', 'Leishmania amastigote', 'Leishmania is transmitted as a promastigote by a sand fly and becomes an amastigote within human phagocytic cells. The nucleus-plus-kinetoplast morphology supports this parasite group; the intracellular nonflagellated form differs from the vector-associated elongated form.', [['Leishmania promastigote with a prominent external flagellum','Promastigotes are associated with the sand fly and initial inoculum rather than the typical intracellular tissue form.'],['Plasmodium sporozoite within macrophages','Sporozoites first target hepatocytes and do not match the kinetoplast-containing tissue form.'],['Schistosoma cercaria within a blood cell','Cercariae are multicellular skin-penetrating trematode larvae rather than tiny intracellular protozoa.']], 'Identify the Leishmania tissue form from intracellular kinetoplast-containing organisms.','leishmania'),
q('Microbiology','Hematology','Babesia erythrocytic tetrads','A person develops fever and hemolytic anemia after tick exposure in the northeastern United States. A blood smear contains intraerythrocytic ring forms and occasional tetrads arranged as a cross. Which organism best fits?', 'Babesia species', 'Babesia can form intraerythrocytic ring forms and characteristic tetrads, sometimes described as a Maltese cross. Tick exposure and hemolysis support the interpretation. Ring forms alone may resemble malaria, so the tetrad and epidemiologic context improve discrimination.', [['Plasmodium falciparum','Falciparum can produce red-cell rings but does not characteristically form the described cross-shaped tetrads.'],['Leishmania donovani','Leishmania tissue amastigotes are found in phagocytes rather than erythrocytic tetrads.'],['Trypanosoma cruzi','Circulating trypomastigotes are extracellular rather than cross-shaped organisms inside red cells.']], 'Integrate tick exposure and erythrocytic tetrads to distinguish babesiosis from malaria.','babesia','integration'),
q('Microbiology','General Principles','Toxoplasma feline sexual cycle','A parasite forms tissue cysts in many warm-blooded animals, but only members of the cat family shed oocysts after the intestinal sexual cycle. What host category do felids occupy?', 'Definitive hosts of Toxoplasma gondii', 'The definitive host is the host in which sexual reproduction occurs. Felids fulfill this role for Toxoplasma gondii, while humans and many other animals can harbor asexual tissue stages. Host category reflects the life-cycle stage rather than which species experiences the most severe illness.', [['Obligatory arthropod vectors','Cats are vertebrate definitive hosts rather than blood-feeding arthropod vectors.'],['The only possible intermediate hosts','Many species can harbor tissue stages, while felids specifically support the sexual cycle.'],['Accidental hosts with no intestinal parasite development','The stem explicitly describes intestinal sexual development in felids.']], 'Assign definitive-host status using the site of Toxoplasma sexual reproduction.','toxoplasma','recognition'),
q('Microbiology','General Principles','Chagas vector fecal inoculation','A triatomine bug feeds near a sleeping person and defecates beside the bite. Scratching introduces parasite-containing material into the wound. Which transmission mechanism is demonstrated?', 'Trypanosoma cruzi entry from infected vector feces', 'Classic vector transmission of T cruzi occurs when infected triatomine feces contaminate a bite wound or mucosal surface. The infective material is not necessarily injected in saliva during feeding, distinguishing this mechanism from several other arthropod-borne infections.', [['Direct salivary injection as the required mechanism','The stem specifically describes contamination by feces rather than obligatory injection in saliva.'],['Ingestion of an intestinal tapeworm cysticercus','The vector-associated protozoan exposure does not involve meat-borne cestode larvae.'],['Penetration by a freshwater cercaria','That is the skin-entry route of schistosomes rather than a triatomine-associated trypanosome.']], 'Distinguish fecal contamination transmission of T cruzi from arthropod salivary inoculation.','cruzi'),
q('Microbiology','Gastrointestinal','Enterobius perianal sampling','A child has intense nocturnal perianal itching but repeated routine stool examinations are unrevealing. Why can an early-morning adhesive-tape sample from perianal skin be more informative?', 'Female pinworms deposit eggs on the perianal skin', 'Enterobius females migrate to the perianal region and lay eggs, commonly at night. Sampling that surface before bathing or toileting targets the egg-deposition site. The method is useful because routine stool collection does not reliably capture the same local deposition.', [['The eggs circulate only in blood at dawn','Pinworm eggs are deposited locally rather than undergoing a required blood circulation phase.'],['Adult worms release cercariae through sweat glands','Cercariae belong to trematode cycles rather than pinworm reproduction.'],['Tape identifies dormant liver hypnozoites','A perianal sample cannot detect a malaria liver reservoir.']], 'Choose the biological reason for perianal rather than routine stool sampling in enterobiasis.','enterobius'),
q('Microbiology','Hematology','Hookworm intestinal blood loss','A person with a substantial intestinal hookworm burden develops low ferritin and microcytic anemia despite adequate dietary iron intake. Which parasite effect best explains the iron deficit?', 'Chronic blood loss at intestinal attachment and feeding sites', 'Adult intestinal hookworms attach to mucosa and feed on blood, causing ongoing iron loss when the burden is sufficient. This mechanism differs from direct destruction of circulating erythrocytes or selective failure of marrow heme enzymes, even though all can contribute to anemia in other settings.', [['Direct replication inside circulating erythrocytes','Hookworms are intestinal helminths rather than intraerythrocytic protozoa.'],['Selective inhibition of intrinsic-factor production','That mechanism produces vitamin B12 malabsorption rather than the stated iron-loss pattern.'],['Sequestration of all iron within liver hypnozoites','Hookworms do not have dormant malaria-like liver stages.']], 'Explain hookworm-associated iron deficiency through ongoing intestinal blood loss.','hookworm'),
q('Microbiology','Respiratory','Ascaris lung migration','After ingestion of embryonated Ascaris eggs, a patient develops transient cough and eosinophilia before mature worms are detectable in stool. Which normal life-cycle event explains this early pulmonary phase?', 'Larval migration through the lungs before return to the intestine', 'Ascaris larvae hatch, migrate through tissues to the lungs, ascend the airway and are swallowed before maturing in the intestine. The early pulmonary manifestations can therefore precede egg production by adult worms, so an early negative stool egg examination does not exclude this migratory phase.', [['Permanent maturation of adult worms in alveoli','Adult Ascaris usually mature in the intestine rather than permanently inhabiting alveoli.'],['Direct inhalation of adult worms from soil','The cycle begins with ingestion of infective eggs rather than inhalation of adults.'],['A required mosquito injection into pulmonary arteries','Ascaris transmission does not require a mosquito vector.']], 'Relate early eosinophilic pulmonary symptoms to the prepatent Ascaris larval migration phase.','ascaris'),
q('Microbiology','Gastrointestinal','Trichuris bipolar plug eggs','A stool specimen from a child with chronic intestinal symptoms contains barrel-shaped eggs with prominent plugs at both poles. Which nematode is most consistent with this morphology?', 'Trichuris trichiura', 'Trichuris eggs characteristically have a barrel or lemon-like outline with bipolar plugs. Egg morphology can distinguish this whipworm from common intestinal nematodes with oval, planoconvex or mammillated eggs. The finding identifies a parasite rather than establishing the severity of the infection.', [['Enterobius vermicularis','Pinworm eggs are typically planoconvex rather than barrel-shaped with symmetric bipolar plugs.'],['Ascaris lumbricoides','Fertilized Ascaris eggs typically have a thick shell with an outer mammillated layer rather than bipolar plugs.'],['Intestinal hookworm','Hookworm eggs are thin-shelled and oval with developing embryos rather than prominent polar plugs.']], 'Recognize Trichuris eggs from their characteristic bipolar-plug morphology.','trichuris','recognition'),
q('Microbiology','General Principles','Onchocerca skin microfilariae','A patient from a riverine endemic area has pruritic skin disease and subcutaneous nodules. Onchocerca is suspected. Why is a superficial skin snip more appropriate than relying only on a routine blood smear?', 'The microfilariae principally inhabit skin and may involve ocular tissues', 'Onchocerca microfilariae occur predominantly in skin and can migrate into ocular tissues, whereas adult worms commonly occupy subcutaneous nodules. Their tissue distribution explains skin-snip sampling and distinguishes the infection from filarial species whose microfilariae characteristically circulate in blood.', [['All filarial microfilariae are confined to blood at every stage','Filarial species differ in microfilarial distribution; Onchocerca is chiefly dermal.'],['Adult worms develop only within erythrocytes','The adults are tissue nematodes rather than intraerythrocytic organisms.'],['The diagnostic stage is a cyst in undercooked pork','That exposure and stage do not describe onchocerciasis.']], 'Use Onchocerca microfilarial tissue distribution to explain skin-snip sampling.','onchocerca'),
q('Microbiology','General Principles','Lymphatic filarial adult habitat','A person with chronic Wuchereria bancrofti infection develops lymphatic dilation and persistent leg swelling. Which adult parasite location is most directly linked to this complication?', 'Lymphatic vessels', 'Adult Wuchereria bancrofti inhabit lymphatic vessels, where infection-associated inflammation and remodeling can impair drainage. Chronic lymphedema reflects lymphatic dysfunction rather than the direct filling of small arteries by adult worms or simple residence in the intestinal lumen.', [['The intestinal lumen as the sole adult habitat','Wuchereria adults occupy lymphatics rather than living solely as intestinal worms.'],['Small intestinal mucosa where adults feed on blood','That adult habitat is characteristic of intestinal hookworms rather than Wuchereria.'],['Erythrocytes as multiplying adult worms','Adult filarial worms do not develop inside red cells.']], 'Connect the adult habitat of Wuchereria with chronic lymphatic drainage impairment.','filaria'),
q('Microbiology','Nervous System','Naegleria nasal neural entry','A previously healthy swimmer develops rapidly progressive meningoencephalitis after warm freshwater entered the nose. Which route allows Naegleria fowleri to reach the brain?', 'Migration along olfactory structures through the cribriform region', 'Naegleria can enter through the nose and reach the central nervous system along olfactory pathways. This explains the association with nasal freshwater exposure rather than ordinary swallowing of water, and distinguishes it from parasites that first establish an intestinal or blood-stage infection.', [['An obligatory intestinal adult-worm stage','Naegleria is an amoeba and does not require maturation into an intestinal helminth.'],['Direct entry only through an infected mosquito bite','This infection is linked to contaminated water entering the nose rather than mosquito inoculation.'],['Release from dormant malaria hypnozoites','Amoebic neural invasion does not involve a Plasmodium hepatic reservoir.']], 'Connect nasal freshwater exposure with the olfactory route of Naegleria brain invasion.','amoeba'),
q('Microbiology','Nervous System','Acanthamoeba tissue cysts','An immunocompromised patient develops subacute granulomatous encephalitis. Brain tissue shows amoebic trophozoites and double-walled cysts. Which feature favors Acanthamoeba over Naegleria in this comparison?', 'Presence of cyst forms within affected human tissue', 'Acanthamoeba can occur as trophozoites and cysts in human tissue and can cause a subacute granulomatous encephalitis. Naegleria causes a typically acute primary amoebic meningoencephalitis and is not identified as tissue cysts in the same way. The tissue stage and time course jointly guide the distinction.', [['Trophozoites alone prove Naegleria in every tissue','Several free-living amoebae have trophozoites, so that form alone is not definitive.'],['Obligatory transmission by an Anopheles mosquito','Neither of these amoebic infections requires an Anopheles mosquito vector.'],['An exclusive location inside erythrocytes','The described brain tissue forms are not an erythrocytic parasite infection.']], 'Integrate a subacute encephalitis pattern and tissue cysts to distinguish Acanthamoeba.','amoeba','integration'),
];

// Preserve the first 25 previously authored specifications; qualify this continuation's review scope.
for (const spec of specs.slice(25)) {
 spec.evidenceNote = `${spec.question.reference[0]}: official page or NIH bibliographic index checked 2026-10-29. CDC DPDx pages were read for parasite life-cycle and morphology claims; NIH HIV glossary and NCI acyclovir/fluconazole entries were read for those drug targets. Other items retain book-level further reading, not assertion-by-assertion validation. Direct NCBI book access encountered human verification. No expert review or current treatment-regimen recommendation is claimed.`;
 spec.semanticReviewNote = `Compared with the actual Microbiology/Pharmacology topic lists in batches 09, 10 and 16 and the original 25 items of batch 11. Distinct target: ${spec.question.objective} Conceptual differences, rather than demographic substitutions, were used; root's cross-bank semantic gate remains required.`;
}
